def cmd(a,timeout=14):
 try:
  p=subprocess.run(a,capture_output=True,text=True,timeout=timeout)
  return p.returncode,p.stdout.strip()
 except Exception as e:return -99,type(e).__name__
def git(p,*args):
 return cmd(['git','-c','safe.directory='+str(p),'-C',str(p),*args])
def remotename(raw):
 raw=raw.strip()
 if not raw:return None
 match=re.search(r'(?:github[.]com[:/])(?:martaxi-boss/)?([^/@]+?)(?:[.]git)?$',raw,re.I)
 if match:return match.group(1)
 return '[remote not canonical, details redacted]'
